export const NARRATIVE_COMPLETE_IDS = new Set<string>(["irelia","jhin","kindred","viego","swain","braum","yasuo","lux","garen","akali","thresh","karma","riven","ekko","senna"]);

export function getNarrativePack(championId: string): ChampionNarrativePack | undefined {
  return NARRATIVE_PACKS.find((p) => p.championId === championId);
}
